def rle_encode(data):
    out, i = [], 0
    while i < len(data):
        j = i
        while j < len(data) and data[j] == data[i]:
            j += 1  # 같은 값이 이어지는 끝 찾기
        out.append((data[i], j - i))  # (값, 반복 횟수)
        i = j
    return out

def rle_decode(pairs):
    return ''.join(v * n for v, n in pairs)
